def _load_achievements() -> dict:
    default = {
        "unlocked": {},
        "stats": {
            "listen_seconds": 0.0,
            "used_char_filter": False,
            "feed_count": 0,
            "diary_count": 0,
            "schedule_count": 0,
            "gather_plays": 0,
            "gather_best": 0,
            "typing_plays": 0,
            "typing_best_grade": "",
            "vocab_plays": 0,
            "vocab_best_streak": 0,
            "rhythm_plays": 0,
            "rhythm_best_grade": "",
            "rhyme_wins": 0,
            "rhyme_jinmu_wins": 0,
            "expose_clears": 0,
            "modes_used": [],
            "mode_seconds": {
                "free": 0.0,
                "follow": 0.0,
                "stroll": 0.0,
                "quiet": 0.0,
                "work": 0.0,
                "game": 0.0,
                "music": 0.0,
            },
            # 结束提示用的会话累计（须在 default 内，否则加载时会被丢弃）
            "work_total_seconds": 0.0,
            "sleep_total_seconds": 0.0,
            "music_total_seconds": 0.0,
            "companion_enabled": False,
            "companion_open_count": 0,
            "owner_named": False,
            "gift_ready": False,
            "pixel_gift": False,
            "weather_peek": False,
            "timer_use": False,
            "memory_open": False,
            "home_visit": False,
            "farm_plant": False,
            "farm_harvest": False,
            "farm_chop": False,
            "farm_fish": False,
            "farm_craft": False,
            "home_paint": False,
            "rpg_play": False,
            "meta_banter": {"last_ms": 0, "event_last": {}, "used": {}},
        },
    }
    if not ACHIEVEMENTS_FILE.exists():
        return default
    try:
        data = json.loads(ACHIEVEMENTS_FILE.read_text(encoding="utf-8"))
        if not isinstance(data, dict):
            return default
        unlocked = data.get("unlocked") if isinstance(data.get("unlocked"), dict) else {}
        stats_in = data.get("stats") if isinstance(data.get("stats"), dict) else {}
        stats = dict(default["stats"])
        # 先合并已知键，再保留文件里多出来的键（避免更新后累计被静默清掉）
        for k, v in default["stats"].items():
            if k == "mode_seconds":
                continue
            if k in stats_in:
                stats[k] = stats_in[k]
        for k, v in stats_in.items():
            if k == "mode_seconds":
                continue
            if k not in stats:
                stats[k] = v
        # normalize types
        stats["listen_seconds"] = float(stats.get("listen_seconds", 0) or 0)
        stats["used_char_filter"] = bool(stats.get("used_char_filter", False))
        stats["modes_used"] = list(stats.get("modes_used") or [])
        stats["companion_open_count"] = int(stats.get("companion_open_count", 0) or 0)
        for tot_key in ("work_total_seconds", "sleep_total_seconds", "music_total_seconds"):
            stats[tot_key] = float(stats.get(tot_key, 0) or 0)
        mode_sec_in = stats_in.get("mode_seconds") if isinstance(stats_in.get("mode_seconds"), dict) else {}
        mode_sec = dict(default["stats"]["mode_seconds"])
        for mk, mv in mode_sec.items():
            mode_sec[mk] = float(mode_sec_in.get(mk, mv) or 0)
        # 文件里若还有其它 mode 桶键也保留
        for mk, mv in mode_sec_in.items():
            if mk not in mode_sec:
                mode_sec[str(mk)] = float(mv or 0)
        stats["mode_seconds"] = mode_sec
        # 回填：若会话累计曾被加载逻辑丢掉，用 mode_seconds 托底
        heal_map = (
            ("work_total_seconds", "work"),
            ("sleep_total_seconds", "quiet"),
            ("music_total_seconds", "music"),
        )
        healed = False
        for tot_key, mode_key in heal_map:
            live = float(mode_sec.get(mode_key, 0) or 0)
            cur = float(stats.get(tot_key, 0) or 0)
            if live > cur + 0.5:
                stats[tot_key] = live
                healed = True
        out = {
            "unlocked": {str(k): v for k, v in unlocked.items()},
            "stats": stats,
        }
        if healed:
            try:
                _save_achievements(out)
            except Exception:
                pass
        return out
    except Exception:
        return default


def _save_achievements(data: dict) -> None:
    ACHIEVEMENTS_FILE.parent.mkdir(parents=True, exist_ok=True)
    ACHIEVEMENTS_FILE.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")


def _music_slug_id(stem: str) -> str:
    mapped = MUSIC_TRACK_ID_MAP.get(stem)
    if mapped:
        return mapped
    slug = re.sub(r"[^0-9A-Za-z]+", "_", stem).strip("_").lower()
    if slug:
        return slug
    return f"track_{abs(hash(stem)) % 10**8:x}"


def _build_music_tracks() -> tuple[dict[str, dict], tuple[str, ...]]:
    tracks: dict[str, dict] = {}
    if not MUSIC_SRC_DIR.is_dir():
        return tracks, ()
    # 支持颜色子目录：Vpetmusic/<color-folder>/*.wav
    for path in sorted(MUSIC_SRC_DIR.rglob("*"), key=lambda p: str(p).lower()):
        if not path.is_file() or not is_audio_media(path):
            continue
        try:
            rel = path.relative_to(MUSIC_SRC_DIR)
        except ValueError:
            continue
        folder = rel.parts[0] if len(rel.parts) > 1 else ""
        stem = path.stem
        tid = _music_slug_id(stem)
        title = MUSIC_TRACK_TITLE_MAP.get(tid) or stem
        # 同 id 重复时保留先出现的
        if tid in tracks:
            continue
        tracks[tid] = {
            "id": tid,
            "title": title,
            "src": path,
            "cache": DATA_AUDIO_DIR / f"music_{tid}_cache.wav",
            "phonograph": f"音乐·{title}",
            "folder": folder,
            "color_key": _music_folder_color_key(folder),
            "wave_colors": _music_wave_colors_for_folder(folder),
            "char_id": _music_char_id_for_folder(folder),
        }
    order: list[str] = []
    for tid in MUSIC_TRACK_PREFERRED_ORDER:
        if tid in tracks:
            order.append(tid)
    for tid in sorted(tracks.keys(), key=lambda t: str(tracks[t]["title"]).lower()):
        if tid not in order:
            order.append(tid)
    return tracks, tuple(order)


MUSIC_TRACKS, MUSIC_TRACK_ORDER = _build_music_tracks()
