def _resolve_border_file(stem: str) -> Path | None:
    roots = (ASSETS_DIR / "ui", Path(__file__).resolve().parent)
    for root in roots:
        for ext in (".png", ".jpg", ".jpeg"):
            path = root / f"{stem}{ext}"
            if path.is_file():
                return path
    return None


def _load_speech_border_asset(stem: str) -> Image.Image | None:
    path = _resolve_border_file(stem)
    if path is None:
        return None
    try:
        return _strip_border2_outer_white(Image.open(path).convert("RGBA"))
    except Exception:
        return None


def _load_border_asset(stem: str) -> Image.Image | None:
    if not stem:
        return None
    path = _resolve_border_file(stem)
    if path is None:
        return None
    try:
        return _remove_green(Image.open(path).convert("RGBA"))
    except Exception:
        return None


def _cutout_near_black(img: Image.Image, *, thresh: int = 40) -> Image.Image:
    rgba = img.convert("RGBA")
    px = rgba.load()
    w, h = rgba.size
    for y in range(h):
        for x in range(w):
            r, g, b, a = px[x, y]
            if r <= thresh and g <= thresh and b <= thresh:
                px[x, y] = (0, 0, 0, 0)
            elif max(r, g, b) <= thresh + 16 and abs(r - g) < 10 and abs(g - b) < 10:
                px[x, y] = (0, 0, 0, 0)
    return rgba


def _strip_border2_outer_white(img: Image.Image) -> Image.Image:
    """去掉对话边框贴边的白色外圈，保留框体与中间区域。"""
    from collections import deque

    rgba = img.convert("RGBA")
    w, h = rgba.size
    px = rgba.load()

    def is_white(x: int, y: int) -> bool:
        r, g, b, a = px[x, y]
        return a > 80 and r > 198 and g > 198 and b > 198

    outer: set[tuple[int, int]] = set()
    q: deque[tuple[int, int]] = deque()
    for x in range(w):
        q.append((x, 0))
        q.append((x, h - 1))
    for y in range(h):
        q.append((0, y))
        q.append((w - 1, y))
    while q:
        x, y = q.popleft()
        if (x, y) in outer or x < 0 or x >= w or y < 0 or y >= h:
            continue
        if not is_white(x, y):
            continue
        outer.add((x, y))
        q.append((x - 1, y))
        q.append((x + 1, y))
        q.append((x, y - 1))
        q.append((x, y + 1))
    for x, y in outer:
        px[x, y] = (0, 0, 0, 0)
    return rgba


def _speech_border2_base_image() -> Image.Image | None:
    global _SPEECH_BORDER2_BASE
    if _SPEECH_BORDER2_BASE is not None:
        return _SPEECH_BORDER2_BASE
    _SPEECH_BORDER2_BASE = _load_speech_border_asset(SPEECH_BORDER_STEM)
    return _SPEECH_BORDER2_BASE


def _speech_border2_scale_for_content(content_w: int, content_h: int) -> float:
    base = _speech_border2_base_image()
    src_w, src_h = base.size if base is not None else (766, 132)
    inner_w = max(1, src_w - SPEECH_BORDER2_SRC_LEFT - SPEECH_BORDER2_SRC_RIGHT)
    inner_h = max(1, src_h - SPEECH_BORDER2_SRC_TOP - SPEECH_BORDER2_SRC_BOTTOM)
    scale = max(content_w / inner_w, content_h / inner_h, SPEECH_BORDER2_MIN_H / max(1, src_h))
    return max(0.42, scale) * SPEECH_BORDER_UI_SCALE


def _speech_border2_caps(scale: float) -> tuple[int, int, int, int]:
    left = max(14, int(SPEECH_BORDER2_SRC_LEFT * scale))
    right = max(18, int(SPEECH_BORDER2_SRC_RIGHT * scale))
    top = max(8, int(SPEECH_BORDER2_SRC_TOP * scale))
    bottom = max(8, int(SPEECH_BORDER2_SRC_BOTTOM * scale))
    return left, top, right, bottom


def _speech_border2_target_size(content_w: int, content_h: int) -> tuple[int, int, int, int, int, int]:
    """根据文字区尺寸推边框外框。长文会抬高 scale，须限制左右帽，避免把换行宽度挤窄后裁字。"""
    content_w = max(40, int(content_w))
    content_h = max(16, int(content_h))
    # 尽量保住对话换行宽度，避免「变高 → 左右帽变厚 → 文字区变窄 → 高度不够」裁切
    keep_inner_w = min(content_w, SPEECH_BORDER2_TEXT_WRAP)
    scale = _speech_border2_scale_for_content(content_w, content_h)
    left, top, right, bottom = _speech_border2_caps(scale)
    max_pad_x = max(48, SPEECH_BORDER2_MAX_W - keep_inner_w)
    if left + right > max_pad_x:
        shrink = max_pad_x / float(left + right)
        left = max(14, int(left * shrink))
        right = max(18, int(right * shrink))
    inner_max_w = max(40, SPEECH_BORDER2_MAX_W - left - right)
    content_w = min(content_w, inner_max_w)
    target_w = max(SPEECH_BORDER2_MIN_W, min(SPEECH_BORDER2_MAX_W, content_w + left + right))
    target_h = max(SPEECH_BORDER2_MIN_H, content_h + top + bottom)
    if target_h > SPEECH_BORDER2_MAX_H:
        target_h = SPEECH_BORDER2_MAX_H
        content_h = max(16, target_h - top - bottom)
    return target_w, target_h, left, top, content_w, content_h


def _estimate_wrapped_label_size(text: str, wrap_w: int, font=None) -> tuple[int, int]:
    """按像素换行估算 Label 宽高（补 Tk 对 CJK/等宽字体 reqheight 偏低）。"""
    import tkinter.font as tkfont

    if font is None:
        font = PIXEL_FONT
    wrap_w = max(40, int(wrap_w))
    raw = text if text is not None else ""
    try:
        f = tkfont.Font(font=font)
        line_h = max(14, int(f.metrics("linespace")) + 2)
    except Exception:
        f = None
        line_h = 18
    max_line_w = 0
    total_lines = 0
    for para in raw.split("\n"):
        if not para:
            total_lines += 1
            continue
        if f is None:
            # 粗等宽 + 中文约按字号估宽
            cpl = max(1, wrap_w // 12)
            n = max(1, (len(para) + cpl - 1) // cpl)
            total_lines += n
            max_line_w = max(max_line_w, min(wrap_w, len(para) * 12))
            continue
        x = 0
        lines = 1
        for ch in para:
            cw = max(1, int(f.measure(ch)))
            if x + cw > wrap_w and x > 0:
                lines += 1
                x = cw
            else:
                x += cw
        total_lines += lines
        natural = int(f.measure(para))
        max_line_w = max(max_line_w, min(wrap_w, natural if natural > 0 else wrap_w))
    total_lines = max(1, total_lines)
    return max(40, min(wrap_w, max_line_w) if max_line_w else wrap_w), total_lines * line_h


def _speech_border2_inner_pads(target_w: int, target_h: int) -> tuple[int, int, int, int]:
    """与合成边框一致的内容区内边距（长气泡时限制左右帽，避免挤窄文字区）。"""
    base = _speech_border2_base_image()
    src_h = base.size[1] if base is not None else 132
    scale = target_h / max(1, src_h)
    pad_l, pad_t, pad_r, pad_b = _speech_border2_caps(scale)
    keep_inner = min(SPEECH_BORDER2_TEXT_WRAP, max(40, target_w - 48))
    max_pad_x = max(48, target_w - keep_inner)
    if pad_l + pad_r > max_pad_x:
        shrink = max_pad_x / float(pad_l + pad_r)
        pad_l = max(14, int(pad_l * shrink))
        pad_r = max(18, int(pad_r * shrink))
    return pad_l, pad_t, pad_r, pad_b


def _compose_speech_border2(target_w: int, target_h: int) -> Image.Image | None:
    base = _speech_border2_base_image()
    if base is None:
        return None
    src_w, src_h = base.size
    target_w = max(SPEECH_BORDER2_MIN_W, int(target_w))
    target_h = max(SPEECH_BORDER2_MIN_H, int(target_h))
    key = (target_w, target_h)
    cached = _SPEECH_BORDER2_COMPOSE_CACHE.get(key)
    if cached is not None:
        return cached
    scale = target_h / max(1, src_h)
    # base 已去白边；NEAREST 缩放不重新引入贴边白，避免重复 flood-fill
    scaled = base.resize((max(1, int(src_w * scale)), target_h), Image.NEAREST)
    scaled_w = scaled.size[0]
    left = min(int(SPEECH_BORDER2_SRC_LEFT * scale), max(1, scaled_w // 3))
    right = min(int(SPEECH_BORDER2_SRC_RIGHT * scale), max(1, scaled_w // 4))
    if left + right >= scaled_w:
        left = max(1, scaled_w // 3)
        right = max(1, scaled_w // 4)
    left_cap = scaled.crop((0, 0, left, target_h))
    right_cap = scaled.crop((scaled_w - right, 0, scaled_w, target_h))
    mid_src = scaled.crop((left, 0, scaled_w - right, target_h))
    mid_w = max(8, target_w - left_cap.width - right_cap.width)
    mid = mid_src.resize((mid_w, target_h), Image.NEAREST)
    out = Image.new("RGBA", (target_w, target_h), (0, 0, 0, 0))
    out.paste(left_cap, (0, 0), left_cap)
    out.paste(mid, (left_cap.width, 0), mid)
    out.paste(right_cap, (target_w - right_cap.width, 0), right_cap)
    pad_l, pad_t, pad_r, pad_b = _speech_border2_inner_pads(target_w, target_h)
    inner_w = max(1, target_w - pad_l - pad_r)
    inner_h = max(1, target_h - pad_t - pad_b)
    overlay = Image.new(
        "RGBA",
        (inner_w, inner_h),
        (0, 0, 0, int(255 * SPEECH_TEXT_INNER_ALPHA)),
    )
    out.alpha_composite(overlay, (pad_l, pad_t))
    if len(_SPEECH_BORDER2_COMPOSE_CACHE) > 48:
        _SPEECH_BORDER2_COMPOSE_CACHE.clear()
    _SPEECH_BORDER2_COMPOSE_CACHE[key] = out
    return out


def _strip_border_outer_black(img: Image.Image) -> Image.Image:
    """去掉 border 贴边的黑色外圈，保留框线。"""
    from collections import deque

    rgba = img.convert("RGBA")
    w, h = rgba.size
    px = rgba.load()

    def is_edge_black(x: int, y: int) -> bool:
        r, g, b, a = px[x, y]
        return a > 64 and max(r, g, b) < 52

    outer: set[tuple[int, int]] = set()
    q: deque[tuple[int, int]] = deque()
    for x in range(w):
        q.append((x, 0))
        q.append((x, h - 1))
    for y in range(h):
        q.append((0, y))
        q.append((w - 1, y))
    while q:
        x, y = q.popleft()
        if (x, y) in outer or x < 0 or x >= w or y < 0 or y >= h:
            continue
        if not is_edge_black(x, y):
            continue
        outer.add((x, y))
        q.append((x - 1, y))
        q.append((x + 1, y))
        q.append((x, y - 1))
        q.append((x, y + 1))
    for x, y in outer:
        px[x, y] = (0, 0, 0, 0)
    return _cutout_near_black(rgba)


def _panel_border_base_image() -> Image.Image | None:
    global _PANEL_BORDER_BASE
    if _PANEL_BORDER_BASE is not None:
        return _PANEL_BORDER_BASE
    _PANEL_BORDER_BASE = _load_border_asset(PANEL_BORDER_STEM)
    return _PANEL_BORDER_BASE


def _nine_slice_border_image(base: Image.Image, out_w: int, out_h: int, corner_src: int) -> Image.Image:
    src_w, src_h = base.size
    c = min(max(8, corner_src), src_w // 3, src_h // 3)
    out_w = max(c * 2 + 4, int(out_w))
    out_h = max(c * 2 + 4, int(out_h))
    out = Image.new("RGBA", (out_w, out_h), (0, 0, 0, 0))

    def blit(sx0: int, sy0: int, sx1: int, sy1: int, dx0: int, dy0: int, dx1: int, dy1: int) -> None:
        dw, dh = dx1 - dx0, dy1 - dy0
        if dw <= 0 or dh <= 0:
            return
        part = base.crop((sx0, sy0, sx1, sy1)).resize((dw, dh), Image.NEAREST)
        out.paste(part, (dx0, dy0), part)

    blit(0, 0, c, c, 0, 0, c, c)
    blit(c, 0, src_w - c, c, c, 0, out_w - c, c)
    blit(src_w - c, 0, src_w, c, out_w - c, 0, out_w, c)
    blit(0, c, c, src_h - c, 0, c, c, out_h - c)
    blit(c, c, src_w - c, src_h - c, c, c, out_w - c, out_h - c)
    blit(src_w - c, c, src_w, src_h - c, out_w - c, c, out_w, out_h - c)
    blit(0, src_h - c, c, src_h, 0, out_h - c, c, out_h)
    blit(c, src_h - c, src_w - c, src_h, c, out_h - c, out_w - c, out_h)
    blit(src_w - c, src_h - c, src_w, src_h, out_w - c, out_h - c, out_w, out_h)
    return out


def _panel_border_corner_px(out_w: int = 0, out_h: int = 0) -> int:
    base = _panel_border_base_image()
    if base is None:
        return 14
    src_w, src_h = base.size
    c = min(max(8, PANEL_BORDER_CORNER_SRC), src_w // 3, src_h // 3)
    if out_w > 0 and out_h > 0:
        c = min(c, out_w // 4, out_h // 4)
        c = max(12, c)
    return c


def _compose_panel_border(target_w: int, target_h: int) -> Image.Image | None:
    key = (int(target_w), int(target_h))
    cached = _PANEL_BORDER_COMPOSE_CACHE.get(key)
    if cached is not None:
        return cached
    base = _panel_border_base_image()
    if base is None:
        return None
    corner = _panel_border_corner_px(target_w, target_h)
    out = _nine_slice_border_image(base, target_w, target_h, corner)
    inner_w = max(1, target_w - corner * 2)
    inner_h = max(1, target_h - corner * 2)
    overlay = Image.new(
        "RGBA",
        (inner_w, inner_h),
        THEME_BG_INNER_RGBA,
    )
    out.alpha_composite(overlay, (corner, corner))
    out = decorate_panel_border(out, corner, resolve_signs_dir(BUNDLE_DIR))
    out = _remove_green(out)
    if len(_PANEL_BORDER_COMPOSE_CACHE) > 24:
        _PANEL_BORDER_COMPOSE_CACHE.clear()
    _PANEL_BORDER_COMPOSE_CACHE[key] = out
    return out


def _plate_border_image(size: int) -> Image.Image | None:
    cached = _PLATE_BORDER_CACHE.get(size)
    if cached is not None:
        return cached
    border = _load_border_asset(PANEL_BORDER_STEM)
    if border is None:
        return None
    try:
        border = border.resize((size, size), Image.NEAREST)
        _PLATE_BORDER_CACHE[size] = border
        return border
    except Exception:
        return None


def _scale_rgba_alpha(img: Image.Image, factor: float) -> Image.Image:
    rgba = img.convert("RGBA")
    r, g, b, a = rgba.split()
    a = a.point(lambda v, f=factor: max(0, min(255, int(v * f))))
    return Image.merge("RGBA", (r, g, b, a))


def _make_pixel_headphone_icon(size: int = 18) -> Image.Image:
    """菜单用像素耳机图标。"""
    img = Image.new("RGBA", (16, 16), (0, 0, 0, 0))
    d = ImageDraw.Draw(img)
    band = "#88ccff"
    cup = "#66aadd"
    dark = "#223355"
    # headband
    d.rectangle([3, 2, 12, 3], fill=band)
    d.rectangle([2, 3, 3, 7], fill=band)
    d.rectangle([12, 3, 13, 7], fill=band)
    # ear cups
    d.rectangle([1, 7, 5, 13], fill=cup)
    d.rectangle([10, 7, 14, 13], fill=cup)
    d.rectangle([2, 8, 4, 12], fill="#aadfff")
    d.rectangle([11, 8, 13, 12], fill="#aadfff")
    d.rectangle([1, 7, 5, 13], outline=dark)
    d.rectangle([10, 7, 14, 13], outline=dark)
    return img.resize((size, size), Image.NEAREST)


_MENU_KIND_ICON_CACHE: dict[tuple[str, int], ImageTk.PhotoImage] = {}


def _menu_kind_icon_photo(kind: str, size: int = 16) -> ImageTk.PhotoImage:
    key = (kind, int(size))
    photo = _MENU_KIND_ICON_CACHE.get(key)
    if photo is not None:
        return photo
    if kind == "music":
        img = _make_pixel_headphone_icon(size)
    else:
        img = _make_pixel_music_fallback_icon(abs(hash(kind)), size)
    photo = ImageTk.PhotoImage(img)
    _MENU_KIND_ICON_CACHE[key] = photo
    return photo


def _make_pixel_music_fallback_icon(index: int, size: int = 48) -> Image.Image:
    """曲目版面图标：像素音符 + 色块（按曲目序号换色）。"""
    palette = (
        "#66ccff",
        "#ff88cc",
        "#ffcc66",
        "#88ffaa",
        "#cc88ff",
        "#88aaff",
        "#ffaa88",
        "#aaffcc",
    )
    col = palette[index % len(palette)]
    img = Image.new("RGBA", (16, 16), (0, 0, 0, 0))
    d = ImageDraw.Draw(img)
    # stem
    d.rectangle([10, 2, 12, 11], fill=col)
    # flag
    d.rectangle([7, 2, 10, 5], fill=col)
    # note head
    d.ellipse([4, 9, 11, 14], fill=col)
    d.rectangle([1, 1, 14, 14], outline="#223355")
    return img.resize((size, size), Image.NEAREST)


def _music_track_content_image(track_id: str, inner: int) -> Image.Image:
    try:
        idx = list(MUSIC_TRACK_ORDER).index(track_id)
    except ValueError:
        idx = abs(hash(track_id)) % max(1, len(MUSIC_TRACK_ORDER) or 1)
    return _make_pixel_music_fallback_icon(idx, inner)


def _music_track_icon_image(track_id: str, size: int = MUSIC_PLATE_ICON_PX) -> Image.Image:
    """版面图标 = 中间标识（略透明）+ border 外框。"""
    inner = max(16, int(size * MUSIC_PLATE_INNER_RATIO))
    content = _music_track_content_image(track_id, inner)
    content = _scale_rgba_alpha(content, MUSIC_PLATE_INNER_ALPHA)
    canvas = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    # 中间轻微底色，避免边框内太空
    pad = (size - inner) // 2
    fill = Image.new("RGBA", (inner, inner), (12, 18, 28, 55))
    canvas.paste(fill, (pad, pad), fill)
    canvas.paste(content, (pad, pad), content)
    border = _plate_border_image(size)
    if border is not None:
        canvas.alpha_composite(border)
    else:
        # 无边框素材时画一圈简易描边
        d = ImageDraw.Draw(canvas)
        d.rectangle([1, 1, size - 2, size - 2], outline="#66ccff")
        d.rectangle([3, 3, size - 4, size - 4], outline="#88e0ff")
    return canvas


def _music_track_icon_photo(track_id: str, size: int = MUSIC_PLATE_ICON_PX) -> ImageTk.PhotoImage:
    key = (str(track_id), int(size), "pixel_v1")
    photo = _MUSIC_ICON_PHOTO_CACHE.get(key)
    if photo is None:
        photo = ImageTk.PhotoImage(_music_track_icon_image(track_id, size))
        _MUSIC_ICON_PHOTO_CACHE[key] = photo
    return photo



def _ensure_data_dirs() -> None:
    for folder in (
        DATA_DIR,
        DATA_AUDIO_DIR,
        VOICE_CACHE_DIR,
        PHONOGRAPH_USER_DIR,
        SPRITES_DIR,
        PROPS_DIR,
        MINIPET_DIR,
        AUDIO_ASSET_DIR,
    ):
        folder.mkdir(parents=True, exist_ok=True)
    _seed_local_runtime_assets()


def _seed_builtin_audio() -> None:
    """首次运行或打包版：把内置 type_cache 等拷到 data/audio。"""
    for name in ("type_cache.wav", "call_cache.wav"):
        dst = DATA_AUDIO_DIR / name
        if dst.is_file():
            continue
        for src in (
            BUNDLE_DIR / name,
            BUNDLE_DIR / "data" / "audio" / name,
            Path(__file__).resolve().parent / name,
            Path(__file__).resolve().parent / "data" / "audio" / name,
        ):
            if src.is_file():
                try:
                    shutil.copy2(src, dst)
                except Exception:
                    pass
                break


def _seed_local_runtime_assets() -> None:
    """缺资源时优先落到本地目录，避免运行时再去别处找。"""
    DATA_AUDIO_DIR.mkdir(parents=True, exist_ok=True)
    VOICE_CACHE_DIR.mkdir(parents=True, exist_ok=True)
    PROPS_DIR.mkdir(parents=True, exist_ok=True)
    SPRITES_DIR.mkdir(parents=True, exist_ok=True)
    MINIPET_DIR.mkdir(parents=True, exist_ok=True)
    _seed_builtin_audio()
    root = Path(__file__).resolve().parent
    for name in ("box.jpg", "flag.jpg"):
        dst = PROPS_DIR / name
        if dst.is_file():
            continue
        for src in (
            PROPS_DIR / name,
            root / name,
            root / "props" / name,
            BUNDLE_DIR / name,
            BUNDLE_DIR / "props" / name,
            BUNDLE_DIR / "assets" / "props" / name,
        ):
            if src.is_file() and src.resolve() != dst.resolve():
                try:
                    shutil.copy2(src, dst)
                except Exception:
                    pass
                break


def _migrate_legacy_layout() -> None:
    if getattr(sys, "frozen", False):
        return
    root = Path(__file__).resolve().parent
    for name in (
        "app_config.json",
        "pet_profile.json",
        "food_inventory.json",
        "diary.json",
        "schedules.json",
        "music_config.json",
        "pet_id_registry.json",
        "vocab.json",
        "ai_config.json",
    ):
        src, dst = root / name, DATA_DIR / name
        if src.is_file() and not dst.exists():
            shutil.copy2(src, dst)
    for name in (
        "call_cache.wav",
        "type_cache.wav",
    ):
        src, dst = root / name, DATA_AUDIO_DIR / name
        if src.is_file() and not dst.exists():
            shutil.copy2(src, dst)
    for path in root.glob("*.jpg"):
        name = path.name
        if name in {"box.jpg", "flag.jpg"}:
            dst = PROPS_DIR / name
        elif name.startswith("pet"):
            dst = MINIPET_DIR / name
        else:
            dst = SPRITES_DIR / name
        if not dst.exists():
            shutil.copy2(path, dst)


def _asset_path(filename: str) -> Path:
    if filename.startswith("pet"):
        for base in (MINIPET_DIR, SPRITES_DIR, BUNDLE_DIR):
            path = base / filename
            if path.is_file():
                return path
    if filename in {"box.jpg", "flag.jpg"}:
        path = PROPS_DIR / filename
        if path.is_file():
            return path
    for base in (SPRITES_DIR, PROPS_DIR, MINIPET_DIR, BUNDLE_DIR):
        path = base / filename
        if path.is_file():
            return path
    return SPRITES_DIR / filename


