def _normalize_schedule_time(raw: str) -> str | None:
    text = raw.strip()
    if not text:
        return None
    if len(text) == 4 and text.isdigit():
        text = f"{text[:2]}:{text[2:]}"
    for fmt in ("%H:%M", "%H:%M:%S"):
        try:
            return datetime.strptime(text, fmt).strftime("%H:%M")
        except ValueError:
            continue
    if len(text) == 5 and text[2] == ":":
        hour, minute = text.split(":", 1)
        if hour.isdigit() and minute.isdigit():
            h, m = int(hour), int(minute)
            if 0 <= h <= 23 and 0 <= m <= 59:
                return f"{h:02d}:{m:02d}"
    return None


def _normalize_schedule_weekdays(raw) -> list[int] | None:
    """None 表示每天；否则为 0=周一 … 6=周日 的列表。"""
    if raw is None or raw == "daily":
        return None
    if not isinstance(raw, list):
        return None
    days = sorted({int(d) for d in raw if isinstance(d, (int, float)) and 0 <= int(d) <= 6})
    if not days or len(days) >= 7:
        return None
    return days


def _format_schedule_weekdays(item: dict) -> str:
    days = _normalize_schedule_weekdays(item.get("weekdays"))
    if days is None:
        return "每天"
    return " ".join(WEEKDAY_LABELS[d] for d in days)


def _schedule_matches_today(item: dict, weekday: int) -> bool:
    days = _normalize_schedule_weekdays(item.get("weekdays"))
    if days is None:
        return True
    return weekday in days


def _default_full_music_playlist() -> list[str]:
    """默认播放列表＝曲库全部（不再默认只塞 radical_mat）。"""
    if MUSIC_TRACK_ORDER:
        return list(MUSIC_TRACK_ORDER)
    if DEFAULT_MUSIC_TRACK in MUSIC_TRACKS:
        return [DEFAULT_MUSIC_TRACK]
    return []


def _normalize_music_playlist(raw, *, fallback: str | None = None) -> list[str]:
    """校验播放列表，至少保留一首有效曲。"""
    out: list[str] = []
    if isinstance(raw, list):
        for tid in raw:
            tid = MUSIC_TRACK_LEGACY_IDS.get(str(tid), str(tid))
            if tid in MUSIC_TRACKS and tid not in out:
                out.append(tid)
    if not out:
        fb_list = _default_full_music_playlist()
        if fallback:
            fb = MUSIC_TRACK_LEGACY_IDS.get(str(fallback), str(fallback))
            if fb in MUSIC_TRACKS:
                return [fb]
        return fb_list or ([DEFAULT_MUSIC_TRACK] if DEFAULT_MUSIC_TRACK in MUSIC_TRACKS else [])
    return out


def _music_playlist_from_config(config: dict) -> list[str]:
    raw = config.get("playlist")
    if isinstance(raw, list) and raw:
        return _normalize_music_playlist(raw, fallback=DEFAULT_MUSIC_TRACK)
    # 无 playlist 字段：用整库，避免永远单曲 RADICAL MAT
    return _normalize_music_playlist(_default_full_music_playlist(), fallback=DEFAULT_MUSIC_TRACK)


def _load_music_config() -> dict:
    default = {
        "play_mode": "list",
        "playlist": _default_full_music_playlist(),
        "playlist_folders": _default_music_playlist_folders(),
        "playlist_user_set": False,
        "music_volume": 70,
        "volume": 70,
        "sfx_volume": 80,
        "voice_volume": 80,
        "muted": False,
    }
    if not MUSIC_CONFIG_FILE.exists():
        return default
    try:
        data = json.loads(MUSIC_CONFIG_FILE.read_text(encoding="utf-8"))
        if not isinstance(data, dict):
            return default
        merged = {**default, **data}
        if "music_volume" not in data and "volume" in data:
            merged["music_volume"] = int(data["volume"])
        merged["volume"] = merged["music_volume"]
        user_set = bool(data.get("playlist_user_set"))
        if "playlist" in data and isinstance(data.get("playlist"), list) and data.get("playlist"):
            playlist = _normalize_music_playlist(
                data.get("playlist"),
                fallback=str(data.get("normal_track", DEFAULT_MUSIC_TRACK)),
            )
        else:
            # 旧配置只有 normal_track：扩成整库
            playlist = _normalize_music_playlist(_default_full_music_playlist())
            user_set = False
        # 未手动选曲且仍是「仅默认一首」→ 自动扩成全部曲目（修复随机永远从 RADICAL MAT 单曲循环）
        if (
            not user_set
            and len(MUSIC_TRACK_ORDER) > 1
            and len(playlist) == 1
            and playlist[0] in (DEFAULT_MUSIC_TRACK, str(data.get("normal_track", "")))
        ):
            playlist = _normalize_music_playlist(_default_full_music_playlist())
            user_set = False
            try:
                merged["playlist"] = playlist
                merged["playlist_user_set"] = False
                MUSIC_CONFIG_FILE.parent.mkdir(parents=True, exist_ok=True)
                MUSIC_CONFIG_FILE.write_text(
                    json.dumps({**merged, "playlist": playlist, "playlist_user_set": False}, ensure_ascii=False, indent=2),
                    encoding="utf-8",
                )
            except Exception:
                pass
        raw_folders = data.get("playlist_folders")
        if isinstance(raw_folders, list) and raw_folders:
            folders = [str(f) for f in raw_folders if str(f).strip()]
        else:
            folders = _folders_from_playlist(playlist) or _default_music_playlist_folders()
        # 若有人物文件夹筛选且未细选手动曲目冲突：以 folder 过滤为准
        if isinstance(raw_folders, list) and raw_folders and not user_set:
            playlist = _normalize_music_playlist(_playlist_ids_for_folders(folders))
        merged["playlist"] = playlist
        merged["playlist_folders"] = folders
        merged["playlist_user_set"] = user_set
        play_mode = str(merged.get("play_mode", "list"))
        if play_mode not in ("list", "random"):
            play_mode = "list"
        merged["play_mode"] = play_mode
        return merged
    except Exception:
        return default


def _save_music_config(config: dict) -> None:
    MUSIC_CONFIG_FILE.write_text(json.dumps(config, ensure_ascii=False, indent=2), encoding="utf-8")


def _load_food_inventory() -> dict[str, int]:
    default = {fid: 0 for fid in FOODS}
    if not FOOD_INVENTORY_FILE.exists():
        return default
    try:
        data = json.loads(FOOD_INVENTORY_FILE.read_text(encoding="utf-8"))
        if isinstance(data, dict):
            for fid in FOODS:
                if fid not in data:
                    # 新增种类：本地种子库存，避免背包「种类变少」
                    default[fid] = max(0, int(FOOD_NEW_KIND_SEED))
                else:
                    default[fid] = max(0, int(data.get(fid, 0)))
    except Exception:
        pass
    return default


def _save_food_inventory(inventory: dict[str, int]) -> None:
    payload = {fid: max(0, int(inventory.get(fid, 0))) for fid in FOODS}
    FOOD_INVENTORY_FILE.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")


def _save_weather_cache(city_label: str, payload: dict) -> None:
    try:
        WEATHER_CACHE_FILE.parent.mkdir(parents=True, exist_ok=True)
        blob = {
            "city": str(city_label or ""),
            "saved_at": datetime.now().isoformat(timespec="seconds"),
            "payload": payload,
        }
        WEATHER_CACHE_FILE.write_text(json.dumps(blob, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        pass


def _load_weather_cache(prefer_city: str = "") -> tuple[str, dict] | None:
    if not WEATHER_CACHE_FILE.exists():
        return None
    try:
        data = json.loads(WEATHER_CACHE_FILE.read_text(encoding="utf-8"))
        if not isinstance(data, dict):
            return None
        payload = data.get("payload")
        if not isinstance(payload, dict):
            return None
        label = str(data.get("city") or prefer_city or "缓存")
        return label, payload
    except Exception:
        return None


def _angle_in_arc(angle: float, start: float, span: float) -> bool:
    a = angle % 360
    s = start % 360
    e = (s + span) % 360
    if s <= e:
        return s <= a < e
    return a >= s or a < e


def _expose_blue_span_for_round(base_span: float, round_index: int) -> float:
    """第 1~5 次 QTE 蓝色判定区逐次缩小（round_index 从 0 起）。"""
    idx = max(0, min(len(EXPOSE_BLUE_SPAN_RATIOS) - 1, round_index))
    ratio = EXPOSE_BLUE_SPAN_RATIOS[idx]
    return max(EXPOSE_BLUE_SPAN_MIN, float(base_span) * ratio)


def _draw_expose_qte_ring(
    canvas: tk.Canvas, size: int, blue_start: float, pointer: float, *, blue_span: float = EXPOSE_BLUE_SPAN
) -> None:
    canvas.delete("all")
    cx = cy = size // 2
    outer_r = size // 2 - 6
    inner_r = max(8, outer_r - 12)
    canvas.create_oval(cx - outer_r, cy - outer_r, cx + outer_r, cy + outer_r, fill="#eeeeee", outline="#cccccc", width=2)
    canvas.create_oval(cx - inner_r, cy - inner_r, cx + inner_r, cy + inner_r, fill="#111122", outline="")
    canvas.create_arc(
        cx - outer_r,
        cy - outer_r,
        cx + outer_r,
        cy + outer_r,
        start=blue_start,
        extent=blue_span,
        fill="#4488ff",
        outline="#66aaff",
        width=2,
        style=tk.PIESLICE,
    )
    canvas.create_arc(
        cx - inner_r,
        cy - inner_r,
        cx + inner_r,
        cy + inner_r,
        start=blue_start,
        extent=blue_span,
        fill="#111122",
        outline="",
        style=tk.PIESLICE,
    )
    rad = math.radians(pointer)
    px = cx + int(math.cos(rad) * (outer_r - 2))
    py = cy - int(math.sin(rad) * (outer_r - 2))
    canvas.create_line(cx, cy, px, py, fill="#ff4444", width=3)
    canvas.create_oval(px - 4, py - 4, px + 4, py + 4, fill="#ffcc44", outline="")


def _draw_glitch_fault(canvas: tk.Canvas, width: int, height: int, message: str, phase: int) -> None:
    canvas.delete("all")
    canvas.create_rectangle(2, 2, width - 2, height - 2, fill="#120818", outline="#ff3366", width=2)
    for y in range(0, height, 3):
        if (y + phase) % 7 < 2:
            canvas.create_line(0, y, width, y, fill="#2a1030")
    for i in range(6):
        gy = (phase * 5 + i * 17) % max(1, height - 10)
        gh = 2 + (phase + i) % 4
        col = ("#ff0044", "#00ffcc", "#662244", "#ffaa00")[i % 4]
        canvas.create_rectangle(0, gy, width, gy + gh, fill=col, outline="")
    jitter = int(math.sin(phase * 0.65) * 4)
    canvas.create_text(
        width // 2 + jitter,
        height // 2 - 10,
        text=message,
        fill="#ff88aa",
        font=("Courier New", 11, "bold"),
    )
    canvas.create_text(
        width // 2 - jitter,
        height // 2 + 14,
        text=f"Enter 判定 · 连中{EXPOSE_GLITCH_HITS_REQUIRED}次通关",
        fill="#88ccff",
        font=("Courier New", 9, "bold"),
    )


def _draw_music_wave(
    canvas: tk.Canvas,
    width: int,
    height: int,
    phase: int,
    *,
    colors: tuple[str, ...] | None = None,
    lite: bool = False,
) -> None:
    """像素音波光圈：仅随 phase 自主呼吸，与曲目节奏/响度无关。"""
    canvas.delete("all")
    cx, cy = width // 2, height // 2
    half = min(width, height) // 2
    px = max(4, min(width, height) // 18)
    max_r = max(8, half - px - 1)
    palette = colors if colors and len(colors) >= 2 else DEFAULT_MUSIC_WAVE_COLORS
    base, light = palette[0], palette[1]
    ring_n = 2 if lite else 4
    for ring in range(ring_n):
        wave = 0.5 + 0.5 * math.sin(phase * 0.22 + ring * 0.85)
        frac = 0.48 + ring * (0.22 if lite else 0.16)
        # 缩放范围：约 0.50～1.0（最大不破框）
        pulse = 0.50 + 0.50 * wave
        r = int(max_r * frac * pulse)
        r = max(4, min(r, max_r))
        col = base if ring % 2 == 0 else light
        if lite:
            wline = max(2, px - 1)
            canvas.create_oval(cx - r, cy - r, cx + r, cy + r, outline=col, width=wline)
        else:
            _draw_pixel_ring(canvas, cx, cy, r, px, col)
    if lite:
        return
    bars = 7
    bar_w = max(px, width // (bars * 3))
    gap = bar_w
    total = bars * bar_w + (bars - 1) * gap
    x0 = (width - total) // 2
    for i in range(bars):
        x = x0 + i * (bar_w + gap)
        wave = math.sin(phase * 0.35 + i * 0.8) * 0.5 + 0.5
        h = int(wave * (height // 10) + px)
        col = base if i % 2 == 0 else light
        canvas.create_rectangle(x, height - h - 2, x + bar_w, height - 2, fill=col, outline="")


def _scatter_xy_on_ring(size: int, *, rng: random.Random | None = None) -> tuple[int, int]:
    """在外环随机取点，用于星星/花/心等装饰，避开立绘中心。"""
    r = rng or random
    ang = r.uniform(0, math.tau)
    rad = size * r.uniform(0.34, 0.48)
    return int(size * 0.5 + math.cos(ang) * rad), int(size * 0.5 + math.sin(ang) * rad)


def _music_track(track_id: str | None) -> dict:
    tid = str(track_id or DEFAULT_MUSIC_TRACK).strip() or DEFAULT_MUSIC_TRACK
    tid = MUSIC_TRACK_LEGACY_IDS.get(tid, tid)
    if tid in MUSIC_TRACKS:
        return MUSIC_TRACKS[tid]
    if DEFAULT_MUSIC_TRACK in MUSIC_TRACKS:
        return MUSIC_TRACKS[DEFAULT_MUSIC_TRACK]
    # 兜底：任意一首
    if MUSIC_TRACK_ORDER:
        return MUSIC_TRACKS[MUSIC_TRACK_ORDER[0]]
    return {
        "id": "missing",
        "title": "（无曲目）",
        "src": MUSIC_SRC_DIR / "missing.wav",
        "cache": DATA_AUDIO_DIR / "music_missing_cache.wav",
        "phonograph": "音乐·无曲目",
        "folder": "",
        "color_key": "blue",
        "wave_colors": DEFAULT_MUSIC_WAVE_COLORS,
        "char_id": "eiden",
    }


def _ensure_music_track_wav(track_id: str | None) -> Path | None:
    track = _music_track(track_id)
    return _ensure_audio_wav(Path(track["src"]), Path(track["cache"]))


def _ensure_all_music_track_wavs(*, limit: int | None = 3, prefer: list[str] | None = None) -> None:
    """启动只预热少量曲目；完整转码延后到真正播放时。"""
    order: list[str] = []
    for tid in list(prefer or []):
        tid = MUSIC_TRACK_LEGACY_IDS.get(str(tid), str(tid))
        if tid in MUSIC_TRACKS and tid not in order:
            order.append(tid)
    for tid in MUSIC_TRACK_ORDER:
        if tid not in order:
            order.append(tid)
    if limit is not None:
        order = order[: max(0, int(limit))]
    for i, tid in enumerate(order):
        try:
            _ensure_music_track_wav(tid)
        except Exception:
            pass
        if i and i % 2 == 0:
            time.sleep(0.05)


def _music_playable_path(track_id: str | None) -> Path | None:
    """播放用路径：优先已有 cache；源已是 wav/ogg/mp3 则直接播，禁止主线程 ffmpeg。"""
    track = _music_track(track_id)
    cache = Path(track["cache"])
    src = Path(track["src"])
    try:
        if cache.is_file() and (not src.is_file() or cache.stat().st_mtime >= src.stat().st_mtime):
            return cache
    except Exception:
        if cache.is_file():
            return cache
    if src.is_file() and src.suffix.lower() in (".wav", ".ogg", ".mp3"):
        return src
    # 仅非 pygame 直播格式才同步转码（应极少）
    return _ensure_music_track_wav(track_id)


def _resolve_music_wav(track_id: str | None) -> Path | None:
    return _music_playable_path(track_id)


def _load_ai_config() -> dict:
    config = dict(AI_DEFAULT_CONFIG)
    if AI_CONFIG_FILE.exists():
        try:
            data = json.loads(AI_CONFIG_FILE.read_text(encoding="utf-8"))
            if isinstance(data, dict):
                config.update(data)
        except Exception:
            pass
    if not config.get("api_key"):
        config["api_key"] = (
            os.environ.get("DASHSCOPE_API_KEY", "")
            or os.environ.get("QWEN_API_KEY", "")
            or os.environ.get("OPENAI_API_KEY", "")
            or os.environ.get("DEEPSEEK_API_KEY", "")
        )
    return config


def _apply_font_size(size: int) -> None:
    global PIXEL_FONT
    size = max(8, min(24, int(size)))
    PIXEL_FONT = ("Courier New", size, "bold")


def _load_app_config() -> dict:
    default = {
        "font_size": 12,
        "display_size": DEFAULT_SIZE,
        "display_preset": "中",
        "difficulty": "中",
        "rhythm_speed": "中",
        "rhythm_chart_diff": "中",
        "rhythm_auto": False,
        "weather_city": "北京",
        "seen_hints": {},
        "work_mode": {"show_props": True, "show_stack": True},
        # 睡眠/音乐/工作等自动桌面秒表·计时器是否显示（工具菜单打开的仍可显示）
        "show_timers": True,
        "voice_mode": False,
        # 语音全局触发间隔（毫秒）；仅语音模式开启后可在设置里调
        "voice_interval_ms": VOICE_GLOBAL_COOLDOWN_MS,
        # 难度连续值 0=低 … 1=高（兼容旧 difficulty 字符串）
        "difficulty_t": 0.5,
        # 去掉立绘/画廊最外围连通黑边（仅边缘泛洪，缓存后不卡）
        "strip_outer_black": False,
        # top=置顶 / middle=应用之下、桌面之上 / bottom=最底层（HWND_BOTTOM）
        "display_layer": "top",
        # 人格：default=默认立绘 / nc=金目（nc* 立绘）
        "persona": PERSONA_DEFAULT,
        # 角色身份：aoba=苍叶 / eiden=伊得（双开涨友情）
        "pet_kind": PET_KIND,
        # 桌宠编号服务由内置默认 / 环境变量提供，玩家不可手填
        "pet_id_api_url": "",
        "pet_id_activation_code": "",
    }
    if not APP_CONFIG_FILE.exists():
        return default
    try:
        data = json.loads(APP_CONFIG_FILE.read_text(encoding="utf-8"))
        if isinstance(data, dict):
            return {**default, **data}
    except Exception:
        pass
    return default


def _save_app_config(config: dict) -> None:
    APP_CONFIG_FILE.write_text(json.dumps(config, ensure_ascii=False, indent=2), encoding="utf-8")


