def _draw_pixel_backpack(canvas: tk.Canvas, x: int, y: int, px: int = 2, *, open_bag: bool = False) -> None:
    body_x = x + px
    body_y = y + px * 3
    body_w = px * 8
    body_h = px * 6
    canvas.create_rectangle(body_x, body_y, body_x + body_w, body_y + body_h, fill=THEME_BLUE_DEEP, outline=THEME_BLUE)
    canvas.create_rectangle(body_x + px * 2, body_y - px * 2, body_x + px * 6, body_y, fill=THEME_PINK, outline="")
    if open_bag:
        canvas.create_polygon(
            body_x,
            body_y,
            body_x + body_w // 2,
            body_y + px * 2,
            body_x + body_w,
            body_y,
            fill=THEME_PINK,
            outline=THEME_BLUE,
        )
        canvas.create_oval(body_x + px * 2, body_y + px * 2, body_x + px * 5, body_y + px * 5, fill="#d4a056", outline="")
    else:
        canvas.create_rectangle(body_x, body_y - px, body_x + body_w, body_y + px, fill=THEME_PINK, outline=THEME_BLUE)


def _pick_game_drop_kind() -> tuple[str, str | None]:
    r = random.random()
    if r >= 1.0 - GAME_SPECIAL_DROP_CHANCE:
        special = random.choices(
            ("time_minus", "dizzy", "time_plus"),
            weights=(GAME_TIME_MINUS_WEIGHT, GAME_DIZZY_WEIGHT, GAME_TIME_PLUS_WEIGHT),
            k=1,
        )[0]
        return special, None
    return "food", random.choice(list(FOODS.keys()))


def _hex_to_rgb_tuple(color: str) -> tuple[int, int, int]:
    c = color.lstrip("#")
    if len(c) == 3:
        c = "".join(ch * 2 for ch in c)
    return int(c[0:2], 16), int(c[2:4], 16), int(c[4:6], 16)


def _pil_fill_rect(draw: ImageDraw.ImageDraw, x0: int, y0: int, x1: int, y1: int, fill: str) -> None:
    if x1 <= x0 or y1 <= y0:
        return
    draw.rectangle([x0, y0, x1 - 1, y1 - 1], fill=_hex_to_rgb_tuple(fill))


def _pil_fill_oval(draw: ImageDraw.ImageDraw, x0: int, y0: int, x1: int, y1: int, fill: str) -> None:
    if x1 <= x0 or y1 <= y0:
        return
    draw.ellipse([x0, y0, x1 - 1, y1 - 1], fill=_hex_to_rgb_tuple(fill))


def _pil_fill_poly(draw: ImageDraw.ImageDraw, points: list[tuple[int, int]], fill: str) -> None:
    if len(points) < 3:
        return
    draw.polygon(points, fill=_hex_to_rgb_tuple(fill))


def _pil_draw_pixel_food(draw: ImageDraw.ImageDraw, food_id: str, x: int, y: int, px: int = 4) -> None:
    """纯 Pillow 绘制食物（不用 Canvas/ImageGrab，避免 Win32 黑块）。"""
    r = _pil_fill_rect
    o = _pil_fill_oval
    p = _pil_fill_poly
    if food_id == "bread":
        r(draw, x, y + px, x + px * 4, y + px * 3, "#d4a056")
        r(draw, x + px, y, x + px * 3, y + px, "#e8b870")
    elif food_id == "apple":
        o(draw, x, y + px, x + px * 3, y + px * 4, "#ee4444")
        r(draw, x + px, y, x + px * 2, y + px, "#66aa33")
    elif food_id == "cake":
        r(draw, x, y + px * 2, x + px * 4, y + px * 4, "#ff88cc")
        r(draw, x + px, y + px, x + px * 3, y + px * 2, "#ffcc66")
        r(draw, x + px * 2, y, x + px * 3, y + px, "#ff4466")
    elif food_id == "fish":
        p(draw, [(x, y + px * 2), (x + px * 4, y + px), (x + px * 4, y + px * 3)], "#88bbee")
        r(draw, x + px, y + px, x + px * 2, y + px * 2, "#ffffff")
    elif food_id == "onigiri":
        p(draw, [(x + px * 2, y), (x + px * 4, y + px * 4), (x, y + px * 4)], "#f5f5ee")
        r(draw, x + px, y + px * 2, x + px * 3, y + px * 3, "#224422")
    elif food_id == "candy":
        r(draw, x + px, y + px, x + px * 3, y + px * 3, "#ff6688")
        r(draw, x + px * 2, y, x + px * 3, y + px * 4, "#ffcc44")
    elif food_id == "tea":
        r(draw, x, y + px * 2, x + px * 4, y + px * 4, "#cc8844")
        r(draw, x + px, y + px, x + px * 3, y + px * 2, "#aa6633")
        r(draw, x + px * 2, y, x + px * 3, y + px, "#cccccc")
    elif food_id == "meat":
        o(draw, x, y + px, x + px * 4, y + px * 3, "#cc5533")
        r(draw, x + px, y + px * 2, x + px * 3, y + px * 3, "#aa3322")
    elif food_id == "berry":
        p(
            draw,
            [
                (x + px * 2, y),
                (x + px * 4, y + px * 2),
                (x + px * 3, y + px * 4),
                (x + px, y + px * 4),
                (x, y + px * 2),
            ],
            "#ee3355",
        )
        r(draw, x + px, y, x + px * 2, y + px, "#66aa33")
    elif food_id == "donut":
        o(draw, x, y + px, x + px * 4, y + px * 4, "#d4a056")
        o(draw, x + px, y + px * 2, x + px * 3, y + px * 3, "#111122")
        o(draw, x, y + px, x + px * 4, y + px * 3, "#ff88cc")
    elif food_id == "milk":
        r(draw, x + px, y + px, x + px * 3, y + px * 4, "#f5f8ff")
        r(draw, x + px * 2, y, x + px * 3, y + px, "#88aacc")
    elif food_id == "ramen":
        o(draw, x, y + px * 2, x + px * 4, y + px * 4, "#cc8844")
        r(draw, x + px, y + px, x + px * 3, y + px * 2, "#ffdd88")
        r(draw, x + px, y + px * 2, x + px * 3, y + px * 2 + max(1, px // 2), "#dd6633")
    elif food_id == "sushi":
        r(draw, x, y + px * 2, x + px * 4, y + px * 3, "#ffffff")
        o(draw, x + px, y + px, x + px * 3, y + px * 2, "#ee5566")
        r(draw, x + px, y + px * 3, x + px * 3, y + px * 4, "#224422")
    elif food_id == "cookie":
        o(draw, x + px, y + px, x + px * 3, y + px * 3, "#c98a4a")
        o(draw, x + px * 2, y + px * 2, x + px * 2 + max(1, px // 2), y + px * 2 + max(1, px // 2), "#6b3f22")
    elif food_id == "juice":
        r(draw, x + px, y + px, x + px * 3, y + px * 4, "#ffaa44")
        r(draw, x + px * 2, y, x + px * 3, y + px, "#88cc66")
        r(draw, x + px, y + px * 3, x + px * 3, y + px * 4, "#ff8844")
    elif food_id == "taco":
        p(draw, [(x + px, y + px * 3), (x + px * 4, y + px * 3), (x + px * 3, y + px)], "#e8c060")
        r(draw, x + px, y + px * 2, x + px * 3, y + px * 3, "#66aa44")
    elif food_id == "icecream":
        p(draw, [(x + px * 2, y + px * 3), (x + px, y + px * 4), (x + px * 3, y + px * 4)], "#e8c878")
        o(draw, x + px, y + px, x + px * 3, y + px * 3, "#ffccdd")
    elif food_id == "corn":
        r(draw, x + px * 2, y, x + px * 3, y + px * 4, "#88aa44")
        o(draw, x + px, y + px, x + px * 3, y + px * 4, "#ffdd66")
    else:
        r(draw, x, y + px, x + px * 4, y + px * 3, "#6688aa")


def _pil_center_text(draw: ImageDraw.ImageDraw, xy: tuple[int, int], text: str, fill: str) -> None:
    color = _hex_to_rgb_tuple(fill)
    x, y = xy
    try:
        bbox = draw.textbbox((0, 0), text)
        tw, th = bbox[2] - bbox[0], bbox[3] - bbox[1]
    except Exception:
        try:
            tw, th = draw.textsize(text)  # type: ignore[attr-defined]
        except Exception:
            tw, th = max(8, len(text) * 6), 12
    draw.text((x - tw // 2, y - th // 2), text, fill=color)


def _pil_draw_game_special(draw: ImageDraw.ImageDraw, kind: str, size: int) -> None:
    px = max(5, size // 7)
    cx, cy = size // 2, size // 2
    # 少留外圈，避免色键失败时出现玫红描边感
    pad = max(2, px // 2)
    if kind == "time_plus":
        _pil_fill_rect(draw, pad, pad, size - pad, size - pad, "#1a3344")
        draw.rectangle([pad, pad, size - pad - 1, size - pad - 1], outline=_hex_to_rgb_tuple("#66ddff"), width=2)
        _pil_center_text(draw, (cx, cy), "+3s", "#88ffdd")
    elif kind == "time_minus":
        _pil_fill_rect(draw, pad, pad, size - pad, size - pad, "#3a1a1a")
        draw.rectangle([pad, pad, size - pad - 1, size - pad - 1], outline=_hex_to_rgb_tuple("#ff8888"), width=2)
        _pil_center_text(draw, (cx, cy), "-3s", "#ffaaaa")
    elif kind == "dizzy":
        _pil_fill_rect(draw, pad, pad, size - pad, size - pad, "#2a2244")
        draw.rectangle([pad, pad, size - pad - 1, size - pad - 1], outline=_hex_to_rgb_tuple("#ffcc44"), width=2)
        for i in range(3):
            ang = i * 2.1
            sx = cx + int(math.cos(ang) * px * 2.2) - max(2, px - 1)
            sy = cy + int(math.sin(ang) * px * 2.2) - max(2, px - 1)
            sp = max(2, px - 1)
            _pil_fill_rect(draw, sx + sp, sy, sx + sp * 2, sy + sp, "#ffff66")
            _pil_fill_rect(draw, sx, sy + sp, sx + sp * 3, sy + sp * 2, "#ffff66")
            _pil_fill_rect(draw, sx + sp, sy + sp * 2, sx + sp * 2, sy + sp * 3, "#ffff66")


def _render_game_drop_rgb(kind: str, food_id: str | None, size: int) -> Image.Image:
    """采集下落物：精确 magenta 底供色键抠掉；食物像素放大。"""
    img = Image.new("RGB", (size, size), WORK_CHROMA_RGB)
    draw = ImageDraw.Draw(img)
    if kind == "food" and food_id:
        # 约 5 格像素食物，明显大于旧版 size//10
        px = max(8, size // 5)
        body = px * 4
        dx = max(1, (size - body) // 2)
        dy = max(1, (size - body) // 2)
        _pil_draw_pixel_food(draw, food_id, dx, dy, px=px)
    else:
        _pil_draw_game_special(draw, kind, size)
    img = _force_chroma_key_rgb(img)
    return _crop_rgb_not_color(img, WORK_CHROMA_RGB, pad=1, tol=8)


def _game_drop_photo(root: tk.Misc, kind: str, food_id: str | None, size: int) -> ImageTk.PhotoImage:
    key = (kind, food_id or "", int(size))
    hit = _GAME_DROP_PHOTO_CACHE.get(key)
    if hit is not None:
        return hit
    photo = ImageTk.PhotoImage(_render_game_drop_rgb(kind, food_id, size), master=root)
    _GAME_DROP_PHOTO_CACHE[key] = photo
    return photo


def _draw_game_special_item(canvas: tk.Canvas, kind: str, size: int) -> None:
    px = max(4, size // 8)
    cx, cy = size // 2, size // 2
    pad = px
    if kind == "time_plus":
        canvas.create_rectangle(pad, pad, size - pad, size - pad, fill="#1a3344", outline="#66ddff", width=2)
        canvas.create_text(cx, cy, text="+3s", fill="#88ffdd", font=("Courier New", max(8, px * 2), "bold"))
    elif kind == "time_minus":
        canvas.create_rectangle(pad, pad, size - pad, size - pad, fill="#3a1a1a", outline="#ff8888", width=2)
        canvas.create_text(cx, cy, text="-3s", fill="#ffaaaa", font=("Courier New", max(8, px * 2), "bold"))
    elif kind == "dizzy":
        canvas.create_rectangle(pad, pad, size - pad, size - pad, fill="#2a2244", outline="#ffcc44", width=2)
        for i in range(3):
            ang = i * 2.1
            sx = cx + int(math.cos(ang) * px * 2.2)
            sy = cy + int(math.sin(ang) * px * 2.2)
            _draw_pixel_star(canvas, sx - px, sy - px, px=max(2, px - 1), color="#ffff66")


class SpriteSet:
    def __init__(self, display_size: int) -> None:
        self.display_size = display_size
        self.stand: ImageTk.PhotoImage
        self.stand_angry: ImageTk.PhotoImage
        self.stand_question: ImageTk.PhotoImage
        self.happy: ImageTk.PhotoImage
        self.sleep: tuple[ImageTk.PhotoImage, ImageTk.PhotoImage]
        self.front: tuple[ImageTk.PhotoImage, ImageTk.PhotoImage]
        self.back: tuple[ImageTk.PhotoImage, ImageTk.PhotoImage]
        self.left: tuple[ImageTk.PhotoImage, ImageTk.PhotoImage]
        self.right: tuple[ImageTk.PhotoImage, ImageTk.PhotoImage]
        self.move: tuple[ImageTk.PhotoImage, ImageTk.PhotoImage, ImageTk.PhotoImage]
        self.work_front: tuple[ImageTk.PhotoImage, ImageTk.PhotoImage]
        self.work_back: tuple[ImageTk.PhotoImage, ImageTk.PhotoImage]
        self.work_left: tuple[ImageTk.PhotoImage, ImageTk.PhotoImage]
        self.work_right: tuple[ImageTk.PhotoImage, ImageTk.PhotoImage]
        self.work_stand: ImageTk.PhotoImage
        self.box_img: ImageTk.PhotoImage
        self.flag_img: ImageTk.PhotoImage
        self.kick: ImageTk.PhotoImage
        self.shy: tuple[ImageTk.PhotoImage, ImageTk.PhotoImage]
        self.wink: ImageTk.PhotoImage
        self.like: ImageTk.PhotoImage
        self.sad1: ImageTk.PhotoImage
        self.sad2: ImageTk.PhotoImage
        self.yes: ImageTk.PhotoImage
        self.no: ImageTk.PhotoImage
        self.eat2_only: ImageTk.PhotoImage
        self.music_stand: ImageTk.PhotoImage
        self.music_front: tuple[ImageTk.PhotoImage, ImageTk.PhotoImage]
        self.music_back: tuple[ImageTk.PhotoImage, ImageTk.PhotoImage]
        self.music_left: tuple[ImageTk.PhotoImage, ImageTk.PhotoImage]
        self.music_right: tuple[ImageTk.PhotoImage, ImageTk.PhotoImage]
        self.actions: dict[str, tuple[ImageTk.PhotoImage, ...]]
        self.reload()

    @classmethod
    def from_pack(cls, display_size: int, pack: dict) -> "SpriteSet":
        ss = cls.__new__(cls)
        ss.display_size = display_size
        ss._apply_pack(pack)
        return ss

    def _apply_pack(self, pack: dict) -> None:
        photos = {key: ImageTk.PhotoImage(img) for key, img in _sprite_photo_tasks(pack)}
        _bind_sprite_photos(self, photos, pack)

    def _load(
        self, filename: str, reference_scale: float, *, flip: bool = False, prop_size: int | None = None
    ) -> ImageTk.PhotoImage:
        size = prop_size if prop_size is not None else self.display_size
        canvas = _get_processed_canvas(filename, size, reference_scale, flip=flip)
        return ImageTk.PhotoImage(canvas)

    def reload(self) -> None:
        self._apply_pack(_build_sprite_pack(self.display_size))


def _build_sprite_pack(display_size: int, persona: str | None = None) -> dict:
    persona = persona or _ACTIVE_PERSONA
    ref = _reference_scale(display_size)

    def load_img(
        filename: str,
        *,
        flip: bool = False,
        prop_size: int | None = None,
        scale: float | None = None,
    ) -> Image.Image:
        size = prop_size if prop_size is not None else display_size
        use_scale = scale if scale is not None else ref
        resolved = _resolve_sprite_filename(filename, persona)
        return _get_processed_canvas(resolved, size, use_scale, flip=flip)

    stand_canvas = load_img("stand.jpg")
    return {
        "stand": stand_canvas,
        "stand_angry": _add_sticker(stand_canvas, "angry"),
        "stand_question": _add_sticker(stand_canvas, "question"),
        "stand_like": _add_sticker(stand_canvas, "like"),
        "happy": load_img("happy.jpg"),
        "sleep": (load_img("sleep1.jpg"), load_img("sleep2.jpg")),
        "front": (load_img("walkfront1.jpg"), load_img("walkfront2.jpg")),
        "back": (load_img("walkback1.jpg"), load_img("walkback2.jpg")),
        "left": (load_img("walkleft1.jpg"), load_img("walkleft2.jpg")),
        "right": (load_img("walkleft1.jpg", flip=True), load_img("walkleft2.jpg", flip=True)),
        "move": (load_img("move1.jpg"), load_img("move2.jpg"), load_img("move3.jpg")),
        "work_front": (load_img("workfront1.jpg"), load_img("workfront2.jpg")),
        "work_back": (load_img("workback1.jpg"), load_img("workback2.jpg")),
        "work_left": (load_img("workleft1.jpg"), load_img("workleft2.jpg")),
        "work_right": (load_img("workleft1.jpg", flip=True), load_img("workleft2.jpg", flip=True)),
        "work_stand": load_img("workstand.jpg"),
        # 旗/箱：铺满画布 + magenta 底（勿用桌宠 reference_scale，否则会缩成黑点）
        "box_img": _work_prop_rgb_image("box.jpg"),
        "flag_img": _work_prop_rgb_image("flag.jpg"),
        "kick": load_img("kick.jpg"),
        "shy": (load_img("shy1.jpg"), load_img("shy2.jpg")),
        "wink": load_img("wink.jpg"),
        "like": load_img("like.jpg"),
        "sad1": load_img("sad1.jpg"),
        "sad2": load_img("sad2.jpg"),
        "yes": load_img("yes.jpg"),
        "no": load_img("no.jpg"),
        "eat2_only": load_img("eat2.jpg"),
        "music_stand": load_img("musicstand.jpg"),
        "music_front": (load_img("musicfront1.jpg"), load_img("musicfront2.jpg")),
        "music_back": (load_img("musicback1.jpg"), load_img("musicback2.jpg")),
        "music_left": (load_img("musicleft1.jpg"), load_img("musicleft2.jpg")),
        "music_right": (load_img("musicleft1.jpg", flip=True), load_img("musicleft2.jpg", flip=True)),
        "actions": {
            name: tuple(load_img(file) for file in files) for name, files in SELECT_ACTIONS.items()
        },
    }


def _build_quick_stand_pack(display_size: int, persona: str | None = None) -> dict:
    """启动首帧：开场全部用 sleep1 占位（不加载 stand），加载完成再换正式立绘。"""
    persona = persona or _ACTIVE_PERSONA
    ref = _reference_scale(display_size)
    sleep1 = _get_processed_canvas(
        _resolve_sprite_filename("sleep1.jpg", persona), display_size, ref
    )
    pair = (sleep1, sleep1)
    triple = (sleep1, sleep1, sleep1)
    return {
        "stand": sleep1,
        "stand_angry": sleep1,
        "stand_question": sleep1,
        "stand_like": sleep1,
        "happy": sleep1,
        "sleep": (sleep1, sleep1),
        "front": pair,
        "back": pair,
        "left": pair,
        "right": pair,
        "move": triple,
        "work_front": pair,
        "work_back": pair,
        "work_left": pair,
        "work_right": pair,
        "work_stand": sleep1,
        "box_img": sleep1,
        "flag_img": sleep1,
        "kick": sleep1,
        "shy": pair,
        "wink": sleep1,
        "like": sleep1,
        "sad1": sleep1,
        "sad2": sleep1,
        "yes": sleep1,
        "no": sleep1,
        "eat2_only": sleep1,
        "music_stand": sleep1,
        "music_front": pair,
        "music_back": pair,
        "music_left": pair,
        "music_right": pair,
        "actions": {
            name: tuple(sleep1 for _ in files) for name, files in SELECT_ACTIONS.items()
        },
    }


def _sprite_photos_from_pack(pack: dict) -> dict[str, ImageTk.PhotoImage]:
    """同一 PIL 图复用同一 PhotoImage，减少启动期 Tk 对象创建。"""
    photos: dict[str, ImageTk.PhotoImage] = {}
    by_id: dict[int, ImageTk.PhotoImage] = {}
    for key, img in _sprite_photo_tasks(pack):
        iid = id(img)
        photo = by_id.get(iid)
        if photo is None:
            photo = ImageTk.PhotoImage(img)
            by_id[iid] = photo
        photos[key] = photo
    return photos


def _sprite_photo_tasks(pack: dict) -> list[tuple[str, Image.Image]]:
    tasks: list[tuple[str, Image.Image]] = []
    singles = (
        "stand",
        "stand_angry",
        "stand_question",
        "stand_like",
        "happy",
        "work_stand",
        "box_img",
        "flag_img",
        "kick",
        "wink",
        "like",
        "sad1",
        "sad2",
        "yes",
        "no",
        "eat2_only",
        "music_stand",
    )
    for key in singles:
        tasks.append((key, pack[key]))
    for key in (
        "sleep",
        "front",
        "back",
        "left",
        "right",
        "work_front",
        "work_back",
        "work_left",
        "work_right",
        "shy",
        "music_front",
        "music_back",
        "music_left",
        "music_right",
    ):
        a, b = pack[key]
        tasks.append((f"{key}.0", a))
        tasks.append((f"{key}.1", b))
    move_a, move_b, move_c = pack["move"]
    tasks.extend([("move.0", move_a), ("move.1", move_b), ("move.2", move_c)])
    for name, images in pack["actions"].items():
        for i, img in enumerate(images):
            tasks.append((f"actions.{name}.{i}", img))
    tasks.sort(key=lambda item: (0 if item[0] == "stand" else 1, item[0]))
    return tasks


def _bind_sprite_photos(ss: "SpriteSet", photos: dict[str, ImageTk.PhotoImage], pack: dict) -> None:
    def pair(key: str) -> tuple[ImageTk.PhotoImage, ImageTk.PhotoImage]:
        return photos[f"{key}.0"], photos[f"{key}.1"]

    def triple(key: str) -> tuple[ImageTk.PhotoImage, ImageTk.PhotoImage, ImageTk.PhotoImage]:
        return photos[f"{key}.0"], photos[f"{key}.1"], photos[f"{key}.2"]

    ss.stand = photos["stand"]
    ss.stand_angry = photos["stand_angry"]
    ss.stand_question = photos["stand_question"]
    ss.stand_like = photos["stand_like"]
    ss.happy = photos["happy"]
    ss.sleep = pair("sleep")
    ss.front = pair("front")
    ss.back = pair("back")
    ss.left = pair("left")
    ss.right = pair("right")
    ss.move = triple("move")
    ss.work_front = pair("work_front")
    ss.work_back = pair("work_back")
    ss.work_left = pair("work_left")
    ss.work_right = pair("work_right")
    ss.work_stand = photos["work_stand"]
    ss.box_img = photos["box_img"]
    ss.flag_img = photos["flag_img"]
    ss.kick = photos["kick"]
    ss.shy = pair("shy")
    ss.wink = photos["wink"]
    ss.like = photos["like"]
    ss.sad1 = photos["sad1"]
    ss.sad2 = photos["sad2"]
    ss.yes = photos["yes"]
    ss.no = photos["no"]
    ss.eat2_only = photos["eat2_only"]
    ss.music_stand = photos["music_stand"]
    ss.music_front = pair("music_front")
    ss.music_back = pair("music_back")
    ss.music_left = pair("music_left")
    ss.music_right = pair("music_right")
    ss.actions = {
        name: tuple(photos[f"actions.{name}.{i}"] for i in range(len(pack["actions"][name])))
        for name in pack["actions"]
    }


class DesktopPet:
    DIRECTIONS = ("front", "back", "left", "right")
    DELTAS = {
        "front": (0, MOVE_STEP),
        "back": (0, -MOVE_STEP),
        "left": (-MOVE_STEP, 0),
        "right": (MOVE_STEP, 0),
    }
    FOLLOW_DELTAS = {
        "front": (0, FOLLOW_MOVE_STEP),
        "back": (0, -FOLLOW_MOVE_STEP),
        "left": (-FOLLOW_MOVE_STEP, 0),
        "right": (FOLLOW_MOVE_STEP, 0),
    }

    def __init__(self) -> None:
        _ensure_data_dirs()
        app_cfg = _load_app_config()
        if _reset_operation_guide_if_updated(app_cfg):
            _save_app_config(app_cfg)
        _apply_font_size(int(app_cfg.get("font_size", 12)))
        saved_size = _snap_display_size(int(app_cfg.get("display_size", DEFAULT_SIZE)))
        self.display_size = saved_size
        self.font_size = max(8, min(24, int(app_cfg.get("font_size", 12))))
        self.app_config = app_cfg
        # 本进程角色：CLI/环境变量优先，否则读配置，默认伊得
        cfg_kind = _normalize_pet_kind(app_cfg.get("pet_kind"))
        self.pet_kind = PET_KIND if PET_KIND in PET_KIND_CHOICES else (
            cfg_kind if cfg_kind in PET_KIND_CHOICES else PET_KIND_EIDEN
        )
        self.app_config["pet_kind"] = self.pet_kind
        persona = str(self.app_config.get("persona") or PERSONA_DEFAULT)
        if persona not in PERSONA_LABELS:
            persona = PERSONA_DEFAULT
        set_active_persona(persona)
        set_strip_outer_black(bool(self.app_config.get("strip_outer_black")))
        # nc 套图生成放到后台 _startup_load_worker，避免启动前卡住
        self.pet_profile = _load_pet_profile()
        self.pet_id = self.pet_profile.get("pet_id") if PET_ID_FEATURE else None
        if PET_ID_FEATURE and isinstance(self.pet_id, bool):
            self.pet_id = None
        self.owner_name = _owner_display_name(self.pet_profile)
        self.diary_entries = _load_diary()
        self.vocab_words: list[dict[str, str]] = []
        self.ai_history: list[dict[str, str]] = []
        # 难度：优先连续值；旧档名映射到 t
        try:
            self.difficulty_t = float(self.app_config.get("difficulty_t", 0.5))
        except Exception:
            self.difficulty_t = 0.5
        legacy_diff = str(self.app_config.get("difficulty", "中"))
        if "difficulty_t" not in self.app_config and legacy_diff in DIFFICULTY_T_BY_NAME:
            self.difficulty_t = DIFFICULTY_T_BY_NAME[legacy_diff]
        self.difficulty_t = max(0.0, min(1.0, self.difficulty_t))
        self.difficulty = _difficulty_label_for_t(self.difficulty_t)
        self._mood_decay_counter = 0
        self._apply_difficulty_runtime()
        self._home_move_gate_ms = 0
        self._settings_size_job: str | None = None
        self._settings_font_job: str | None = None

        self.root = tk.Tk()
        self.root.title(f"Vpet · {self._pet_display_name()}")
        self.root.overrideredirect(True)
        self._apply_window_layer(self.root)
        self.root.config(bg="magenta")
        self.root.wm_attributes("-transparentcolor", "magenta")

        self._sprite_cache: dict[int, SpriteSet] = {}
        self._persona_sprite_cache: dict[tuple[int, str], SpriteSet] = {}
        self._sprite_building: set[int] = set()
        self._panel_backpack_sig: tuple | None = None
        self.panel_backpack_open = False
